            for cid,name in list(joined.items()):
                c=core.connect(); rows=c.execute('SELECT event_id,payload FROM events WHERE channel_id=? AND event_id>? ORDER BY event_id',(cid,sent.get(cid,0))).fetchall(); sent[cid]=sent.get(cid,0)
                c.close()
