                    if z.get('type') not in ('message.created','message.reply'): continue
                    m=z.get('message') or {}
                    au=core.user_for_token('') if False else None
                    cc=core.connect(); ar=cc.execute('SELECT username FROM users WHERE id=?',(m.get('author_id'),)).fetchone();cc.close()
