        elif cmd=='PRIVMSG':
            name=parts[1] if len(parts)>1 else '';body=parts[2][1:] if len(parts)>2 and parts[2].startswith(':') else (parts[2] if len(parts)>2 else '')
            cid=next((i for i,n in joined.items() if n==name),None)
